# Every feature on the example files shipped with the module (data/ and
# examples/, generated by data-raw/make_examples.R). Skipped where the files
# are not there (an R CMD check of the built package).
ex <- function(...) test_path("..", "..", ...)
skip_no_examples <- function() skip_if_not(file.exists(ex("examples", "heart_external.csv")), "no examples/")
heart <- function() jmvReadWrite::read_omv(ex("data", "heart_cohort.omv"))
extf <- function(name) list(path = ex("examples", name), filename = name)
no_problem <- function(r) expect_null(r$get("problem"))
src <- readLines(test_path("test-render.R"))
eval(parse(text = src[seq_len(grep("^test_that", src)[1] - 1)]))

test_that("logistic: splines, factors, interaction selection, split, external file, updating", {
    skip_no_examples()
    r <- cpLogistic(data = heart(), dep = "event10", eventLevel = "yes", covs = c("sbp", "chol", "bmi"),
                    splineVars = "age", factors = c("sex", "smoking", "diabetes"),
                    covScales = list(list(var = "sbp", scale = "ten")),
                    refLevels = list(list(var = "smoking", ref = "never")),
                    interactions = list(list("age", "sex"), list("sbp", "diabetes")), intMode = "lrt",
                    splitVar = "period", splitLevel = "2017-2019", extFile = extf("heart_external.csv"),
                    validation = "boot", nBoot = 20, stability = TRUE, updating = TRUE, descTable = TRUE,
                    predTests = TRUE, classif = TRUE, dca = TRUE, sampleSize = TRUE, shapley = TRUE,
                    permImp = TRUE, nPerm = 2, shap = TRUE, shapRow = 1)
    no_problem(r)
    expect_equal(r$samples$asDF$excluded[1], sum(!stats::complete.cases(heart()[heart()$period == "2012-2016",
                 c("event10", "sbp", "chol", "bmi", "age", "sex", "smoking", "diabetes")])))
    chk <- r$extCheck$asDF
    expect_equal(chk$status[chk$var == "smoking"], "Warning")
    expect_match(chk$details[chk$var == "age"], "Age")
    expect_match(chk$details[chk$var == "sbp"], "outside the development range")
    it <- r$intTable$asDF
    expect_match(it$kept[it$term == "age × sex"], "step 1")
    u <- r$updTable$asDF
    expect_false(isTRUE(u$chosen[u$set == u$set[nrow(u)] & u$method == "Original model"] == "✓"))
    expect_equal(heading_problems(r), character(0))
    rx <- cpLogistic(data = heart(), dep = "event10", eventLevel = "yes", covs = c("sbp", "chol"),
                     splineVars = "age", factors = "sex", extFile = extf("heart_external.xlsx"))
    no_problem(rx)
    expect_equal(rx$samples$asDF$n[2], sum(stats::complete.cases(
        openxlsx::read.xlsx(ex("examples", "heart_external.xlsx"))[, c("event10", "sbp", "chol", "Age", "SEX")])))
})

test_that("linear and Cox analyses run on the cohort with every option", {
    skip_no_examples()
    r <- cpLinear(data = heart(), dep = "sbp1y", covs = c("sbp", "bmi"), splineVars = "age",
                  factors = c("smoking", "diabetes"), splitVar = "period", splitLevel = "2017-2019",
                  extFile = extf("heart_external.csv"), validation = "cv", nFolds = 5, nRepeats = 2,
                  updating = TRUE, descTable = TRUE, predTests = TRUE, sampleSize = TRUE, shapley = TRUE,
                  shap = TRUE, calPlot = TRUE)
    no_problem(r)
    expect_equal(heading_problems(r), character(0))
    r <- cpCox(data = heart(), time = "time", status = "status", eventLevel = "event", horizon = 5,
               covs = c("sbp", "chol"), splineVars = "age", factors = c("sex", "smoking", "diabetes"),
               interactions = list(list("age", "sex")), splitVar = "period", splitLevel = "2017-2019",
               extFile = extf("heart_external.csv"), validation = "boot", nBoot = 10, dca = TRUE,
               kmPlot = TRUE, calPlot = TRUE, sampleSize = TRUE, descTable = TRUE)
    no_problem(r)
    expect_equal(r$samples$asDF$n[3], 1000 - sum(!stats::complete.cases(
        utils::read.csv(ex("examples", "heart_external.csv"))[, c("time", "status", "sbp", "chol", "Age", "SEX")])) -
        sum(utils::read.csv(ex("examples", "heart_external.csv"))$smoking == "unknown" &
            stats::complete.cases(utils::read.csv(ex("examples", "heart_external.csv"))[, c("time", "sbp", "chol")])))
    expect_equal(heading_problems(r), character(0))
})

test_that("every published model file validates in the external data", {
    skip_no_examples()
    ext <- utils::read.csv(ex("examples", "heart_external.csv"))
    for (v in c("SEX", "smoking", "diabetes", "event10", "status")) ext[[v]] <- factor(ext[[v]])
    preds <- c("Age", "SEX", "smoking", "sbp", "chol", "bmi", "diabetes")
    run <- function(file, family, ...) {
        a <- switch(family,
            binary = list(dep = "event10", eventLevel = "yes"),
            gaussian = list(dep = "sbp1y"),
            cox = list(dep = "status", eventLevel = "event", time = "time"))
        r <- do.call(cpPublished, c(list(data = ext, modelFile = extf(file), family = family, covs = preds), a, list(...)))
        no_problem(r)
        expect_equal(heading_problems(r), character(0))
        r
    }
    r1 <- run("published_logistic.csv", "binary", updating = TRUE, classif = TRUE, dca = TRUE, calPlot = TRUE, rocPlot = TRUE)
    r2 <- run("published_logistic_semicolon.csv", "binary")
    r3 <- run("published_logistic.xlsx", "binary")
    expect_equal(r2$perf$asDF$est, r1$perf$asDF$est, tolerance = 1e-6)
    expect_equal(r3$perf$asDF$est, r1$perf$asDF$est, tolerance = 1e-10)
    expect_match(r1$check$asDF$details[r1$check$asDF$var == "smoking"], "unknown")
    expect_false(isTRUE(r1$updTable$asDF$chosen[1] == "✓"))
    run("published_linear.csv", "gaussian", updating = TRUE, calPlot = TRUE)
    rc <- run("published_cox.csv", "cox", dca = TRUE, kmPlot = TRUE, calPlot = TRUE)
    rn <- run("published_cox_nobaseline.csv", "cox", horizon = 5)
    expect_equal(rn$perf$asDF$est[1], rc$perf$asDF$est[1], tolerance = 1e-10)
    run("heart_logistic_model.json", "binary", updating = TRUE)
    run("heart_cox_model.json", "cox")
})
